// ------------------------------------------------- The three OS voice lines
// ElevenLabs renders live in public/fishos/voice/. The [tag] prefixes are
// PRODUCT INPUT text (S2.1 Pro emotion tags) — allowed on screen because they
// demo the feature, never as narration echo.
export const VOICE = {
  // Victor's picks from the Sep 1 auditions: A2 bright-morning, B4
  // energized-grin, C3 sigh-weary. Files keep their original names; the
  // durations and the on-screen tag words below are the new truth.
  // TAGS ARE SENTENCE-LENGTH DIRECTION (Victor, Sep 1): the on-screen tag is
  // the actual stacked direction that drove the take, not a single word.
  // `tag` is the leading direction; `input` is the full payload as it would
  // sit in the Fish TTS composer, mid-line markers included. `input` always
  // begins with `tag` (P8 slices the text off it).
  calm: {
    file: "fishos/voice/calm-morning.mp3", // A2-bright-morning
    seconds: 5.53,
    frames: 166, // @30fps
    tag: "[bright, upbeat, glad to see him]",
    input:
      "[bright, upbeat, glad to see him] Morning, Bennett. Six departments reporting. [playful, teasing] You want the good news first?",
  },
  confident: {
    file: "fishos/voice/confident-sales.mp3", // B4-energized-grin
    seconds: 3.93,
    frames: 118,
    tag: "[energized, eager, almost grinning]",
    input:
      "[energized, eager, almost grinning] Two proposals out. [chuckles] One call booked for Thursday.",
  },
  worried: {
    file: "fishos/voice/worried-finance.mp3", // C3-sigh-weary (opens on a sigh)
    seconds: 6.89,
    frames: 207,
    tag: "[weary, tired of repeating himself]",
    input:
      "[weary, tired of repeating himself] [sighs] One invoice. [pause] Three days late. [a touch of reproach] I've mentioned it twice.",
  },
} as const;

